class Solution {
    public int maxNumberOfAlloys(int n, int k, int budget, List<List<Integer>> composition, List<Integer> stock, List<Integer> cost) {
        long ans = 0;
        for (List<Integer> comp : composition) {
            long lo = 0, hi = 200_000_000L, best = 0;
            while (lo <= hi) {
                long mid = (lo + hi) / 2;
                long needed = 0;
                for (int i = 0; i < n; i++) {
                    long req = (long) comp.get(i) * mid - stock.get(i);
                    if (req > 0) needed += req * cost.get(i);
                }
                if (needed <= budget) {
                    best = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            ans = Math.max(ans, best);
        }
        return (int) ans;
    }
}

/**
 * @param {number} n
 * @param {number} k
 * @param {number} budget
 * @param {number[][]} composition
 * @param {number[]} stock
 * @param {number[]} cost
 * @return {number}
 */
var maxNumberOfAlloys = function(n, k, budget, composition, stock, cost) {
    let ans = 0;
    for (const comp of composition) {
        let lo = 0, hi = 200000000, best = 0;
        while (lo <= hi) {
            const mid = (lo + hi) >> 1;
            let needed = 0;
            for (let i = 0; i < n; i++) {
                const req = comp[i] * mid - stock[i];
                if (req > 0) needed += req * cost[i];
            }
            if (needed <= budget) {
                best = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        if (best > ans) ans = best;
    }
    return ans;
};
